#!/usr/bin/env bash
# Stage a copy of the upstream Terraform provider docs carrying the YAML
# frontmatter that upjet's scraper requires.
#
# The ncecere/litellm docs are hand-written rather than generated by
# tfplugindocs, so they have no prelude. upjet's scraper treats a missing
# prelude as a fatal error, and it also derives the Terraform resource name of
# each page from `page_title` -- see scrapeExamples in upjet's
# pkg/registry/meta.go, which seeds resourceName from the scraped title and
# keeps only the segment after the last colon. Emitting the same
# "Provider: resource_name" shape the HashiCorp-published providers use
# therefore both satisfies the scraper and names the resources correctly.
set -euo pipefail

SRC=${1:?source docs directory required}
DST=${2:?destination directory required}
PREFIX=${3:-litellm}

rm -rf "${DST}"
mkdir -p "${DST}"

count=0
for f in "${SRC}"/*.md; do
  [ -e "${f}" ] || continue
  base=$(basename "${f}" .md)
  # Pages are named after the resource with the provider prefix dropped:
  # docs/resources/mcp_server.md documents litellm_mcp_server.
  resource="${PREFIX}_${base}"
  # First non-empty line after the H1 is the summary sentence.
  description=$(awk 'NR > 1 && NF { print; exit }' "${f}")
  {
    echo '---'
    echo 'subcategory: ""'
    echo "page_title: \"LiteLLM: ${resource}\""
    echo 'description: |-'
    echo "  ${description}"
    echo '---'
    echo
    cat "${f}"
  } >"${DST}/${base}.md"
  count=$((count + 1))
done

if [ "${count}" -eq 0 ]; then
  echo "no markdown files found under ${SRC}" >&2
  exit 1
fi

echo "prepared ${count} doc pages for scraping in ${DST}"
